// Converte um evento do backend (system_events) em mensagem WhatsApp.
// Payload esperado:
// {
//   "event": "APPOINTMENT_CONFIRMED",
//   "data": { "phone": "5571...", "customer": "Gabriel", "pet": "Thor",
//             "service": "Banho", "date": "20/08", "time": "15:00",
//             "store": "Pet Shop Bicho Feliz", "value": "R$ 50", "reason": "" }
// }
const e = $json.body || {};
const v = e.data || {};

if (!v.phone) {
  throw new Error('Evento sem data.phone — nao e possivel notificar.');
}

const templates = {
  APPOINTMENT_CREATED:   `Recebemos seu pedido de agendamento! 🐾\n\n🐶 Pet: ${v.pet}\n🛁 Servico: ${v.service}\n📅 ${v.date} as ${v.time}\n\nAssim que a loja confirmar, avisamos voce.`,
  APPOINTMENT_CONFIRMED: `✅ Agendamento confirmado!\n\n🐶 Pet: ${v.pet}\n🛁 Servico: ${v.service}\n📅 ${v.date} as ${v.time}\n\nEstamos esperando voces! ❤️`,
  APPOINTMENT_REJECTED:  `😕 Infelizmente nao conseguimos confirmar seu agendamento para ${v.date} as ${v.time}.\n${v.reason ? 'Motivo: ' + v.reason + '\n' : ''}\nQuer escolher outro horario? E so me dizer!`,
  APPOINTMENT_CANCELLED: `Seu agendamento de ${v.service} para ${v.pet} em ${v.date} as ${v.time} foi cancelado.\nSe quiser remarcar, estou por aqui! 🐾`,
  APPOINTMENT_COMPLETED: `Obrigado pela visita! 🐶✨\nEsperamos que ${v.pet} tenha adorado o ${v.service}. Ate a proxima!`,
  QUOTE_SENT:            `🧾 Orcamento para ${v.pet}:\n${v.items || v.service}\n\nTotal: ${v.value}\n\nDeseja agendar?`,
  REMINDER:              `⏰ Lembrete: amanha tem ${v.service} para ${v.pet} as ${v.time}!\n\nSe precisar remarcar, me avisa por aqui.`,
  HUMAN_HANDOFF:         `Claro! Ja chamei um atendente para falar com voce. 👤\nAguarde um instante.`
};

const text = templates[e.event];
if (!text) {
  return [{ json: { skipped: true, reason: 'evento_sem_template', event: e.event } }];
}

return [{ json: { skipped: false, phone: v.phone, text, event: e.event } }];
